(function(){"use strict";var reduceMotion=window.matchMedia&&window.matchMedia("(prefers-reduced-motion: reduce)").matches;function onReady(callback){if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",callback,{once:true});return}callback()}function toArray(items){return Array.prototype.slice.call(items||[])}function observeOnce(target,callback,threshold){if(!target){return}if(reduceMotion||!("IntersectionObserver"in window)){callback();return}var observer=new IntersectionObserver(function(entries,activeObserver){entries.forEach(function(entry){if(entry.isIntersecting){callback();activeObserver.disconnect()}})},{threshold:threshold||.25});observer.observe(target)}function initRevealBlocks(){var blocks=toArray(document.querySelectorAll(".vt-article .vt-reveal"));if(!blocks.length){return}if(reduceMotion||!("IntersectionObserver"in window)){blocks.forEach(function(block){block.classList.add("in")});return}var observer=new IntersectionObserver(function(entries,activeObserver){entries.forEach(function(entry){if(entry.isIntersecting){entry.target.classList.add("in");activeObserver.unobserve(entry.target)}})},{threshold:.12});blocks.forEach(function(block){observer.observe(block)})}function formatNumber(value,decimals){if(decimals>0){return value.toLocaleString("en-US",{minimumFractionDigits:decimals,maximumFractionDigits:decimals})}return Math.round(value).toLocaleString("en-US")}function initCounterGroup(root,selector,attr,decimalsAttr,readyAttr){if(!root||root.getAttribute(readyAttr)==="true"){return}var counters=toArray(root.querySelectorAll(selector));if(!counters.length){return}root.setAttribute(readyAttr,"true");function setFinalValues(){counters.forEach(function(counter){var target=Number(counter.getAttribute(attr));var decimals=Number(counter.getAttribute(decimalsAttr)||0);counter.textContent=formatNumber(target,decimals)})}function runCounters(){if(reduceMotion||!window.requestAnimationFrame){setFinalValues();return}counters.forEach(function(counter){var target=Number(counter.getAttribute(attr));var decimals=Number(counter.getAttribute(decimalsAttr)||0);var startedAt=null;var duration=900;counter.textContent=formatNumber(0,decimals);function tick(timestamp){if(startedAt===null){startedAt=timestamp}var progress=Math.min((timestamp-startedAt)/duration,1);var eased=1-Math.pow(1-progress,3);counter.textContent=formatNumber(target*eased,decimals);if(progress<1){window.requestAnimationFrame(tick)}}window.requestAnimationFrame(tick)})}observeOnce(root,runCounters,.35)}function initTabs(container,readyAttr){if(!container||container.getAttribute(readyAttr)==="true"){return}var tabs=toArray(container.querySelectorAll('[role="tab"]'));var panels=toArray(container.querySelectorAll('[role="tabpanel"]'));if(!tabs.length||!panels.length){return}container.setAttribute(readyAttr,"true");container.classList.add("is-enhanced");function activateTab(tab,moveFocus){tabs.forEach(function(item){var selected=item===tab;item.setAttribute("aria-selected",selected?"true":"false");item.setAttribute("tabindex",selected?"0":"-1")});panels.forEach(function(panel){var active=panel.id===tab.getAttribute("aria-controls");panel.hidden=!active;panel.classList.toggle("is-active",active)});if(moveFocus){tab.focus()}}tabs.forEach(function(tab,index){tab.addEventListener("click",function(){activateTab(tab,false)});tab.addEventListener("keydown",function(event){var nextIndex=index;if(event.key==="ArrowRight"||event.key==="ArrowDown"){nextIndex=(index+1)%tabs.length}else if(event.key==="ArrowLeft"||event.key==="ArrowUp"){nextIndex=(index-1+tabs.length)%tabs.length}else if(event.key==="Home"){nextIndex=0}else if(event.key==="End"){nextIndex=tabs.length-1}else{return}event.preventDefault();activateTab(tabs[nextIndex],true)})});var selectedTab=tabs.filter(function(tab){return tab.getAttribute("aria-selected")==="true"})[0]||tabs[0];activateTab(selectedTab,false)}function initCostBars(root,fillSelector,attr,readyAttr){if(!root||root.getAttribute(readyAttr)==="true"){return}var fills=toArray(root.querySelectorAll(fillSelector));if(!fills.length){return}root.setAttribute(readyAttr,"true");root.classList.add("is-enhanced");observeOnce(root,function(){fills.forEach(function(fill){fill.style.width=fill.getAttribute(attr)+"%"})},.3)}function initValueBars(root,fillSelector,attr,readyAttr){if(!root||root.getAttribute(readyAttr)==="true"){return}var fills=toArray(root.querySelectorAll(fillSelector));if(!fills.length){return}root.setAttribute(readyAttr,"true");function revealValueBars(){fills.forEach(function(fill){var value=Number(fill.getAttribute(attr));if(Number.isNaN(value)){value=0}value=Math.max(0,Math.min(100,value));fill.style.left="0";fill.style.width=value+"%"})}revealValueBars();observeOnce(root,revealValueBars,.3)}function initBrokerageArticle(){var article=document.querySelector("[data-brokerage-article]");if(!article){return}initCounterGroup(article.querySelector("[data-brokerage-stats]"),"[data-counter]","data-counter","data-counter-decimals","data-brokerage-stats-ready");initTabs(article.querySelector("[data-brokerage-tabs]"),"data-brokerage-tabs-ready");var chart=article.querySelector("[data-brokerage-chart]");initValueBars(chart,"[data-brokerage-bar-value]","data-brokerage-bar-value","data-brokerage-chart-ready")}function initAiCompanyArticle(){initCounterGroup(document.getElementById("aiCompanyStats"),"[data-ai-count]","data-ai-count","data-ai-decimals","data-ai-stats-ready");var selector=document.querySelector("[data-ai-zone-selector]");initTabs(selector,"data-ai-zone-selector-ready");initCostBars(selector,"[data-ai-cost-width]","data-ai-cost-width","data-ai-cost-ready")}function initEmiratesMap(){var mapWidget=document.querySelector("[data-emirates-map]");if(!mapWidget||mapWidget.getAttribute("data-emirates-map-ready")==="true"){return}mapWidget.setAttribute("data-emirates-map-ready","true");mapWidget.classList.add("is-enhanced");var regions=toArray(mapWidget.querySelectorAll("[data-em]"));var panels=toArray(mapWidget.querySelectorAll("[data-em-panel]"));var linkedLabels=toArray(mapWidget.querySelectorAll("[data-lbl]"));function activateEmirate(emirateId,focusPanel){regions.forEach(function(region){var active=region.getAttribute("data-em")===emirateId;region.classList.toggle("is-active",active);region.setAttribute("aria-pressed",active?"true":"false")});linkedLabels.forEach(function(label){label.classList.toggle("is-active",label.getAttribute("data-lbl")===emirateId)});panels.forEach(function(panel){var active=panel.getAttribute("data-em-panel")===emirateId;panel.hidden=!active;if(active&&focusPanel){panel.setAttribute("tabindex","-1");panel.focus({preventScroll:true})}})}regions.forEach(function(region){region.addEventListener("click",function(){activateEmirate(region.getAttribute("data-em"),false)});region.addEventListener("keydown",function(event){if(event.key==="Enter"||event.key===" "){event.preventDefault();activateEmirate(region.getAttribute("data-em"),false)}})});activateEmirate("abudhabi",false)}function initUaeEmiratesArticle(){initEmiratesMap();initTabs(document.querySelector("[data-emirates-business-selector]"),"data-emirates-business-ready");initCounterGroup(document.getElementById("uaeEmiratesStats"),"[data-em-count]","data-em-count","data-em-decimals","data-emirates-stats-ready");initCostBars(document.querySelector("[data-emirates-cost-ladder]"),"[data-em-cost-width]","data-em-cost-width","data-emirates-cost-ready")}onReady(function(){initRevealBlocks();initBrokerageArticle();initAiCompanyArticle();initUaeEmiratesArticle()})})();